import java.util.*;

public class Solution {

    static String process(String text) {
        StringBuilder stack = new StringBuilder();

        for (char ch : text.toCharArray()) {
            if (ch == '#') {
                if (stack.length() > 0) {
                    stack.deleteCharAt(stack.length() - 1);
                }
            } else {
                stack.append(ch);
            }
        }

        return stack.toString();
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        StringBuilder input = new StringBuilder();
        while (sc.hasNext()) {
            if (input.length() > 0) {
                input.append(' ');
            }
            input.append(sc.next());
        }

        String[] parts = input.toString().split("\\s+", 2);

        String s = parts.length > 0 ? parts[0] : "";
        String t = parts.length > 1 ? parts[1] : "";

        System.out.println(process(s).equals(process(t)) ? "true" : "false");
    }
}

