        Stack<Integer> stack = new Stack<>();

        for (int asteroid : asteroids) {
            boolean destroyed = false;

            while (!stack.isEmpty()
                    && asteroid < 0
                    && stack.peek() > 0) {

                if (stack.peek() < -asteroid) {
                    stack.pop();
                    continue;
                }

                if (stack.peek() == -asteroid) {
                    stack.pop();
                }

                destroyed = true;
                break;
            }

            if (!destroyed) {
                stack.push(asteroid);
            }
        }

        System.out.print("[");

        for (int i = 0; i < stack.size(); i++) {
            System.out.print(stack.get(i));

            if (i < stack.size() - 1) {
                System.out.print(",");
            }
        }

        System.out.print("]");
    }
}

