int main() {
    int q;
    scanf("%d", &q);
    getchar();

    char text[MAX_TEXT] = "";
    char line[MAX_TEXT];

    for (int i = 0; i < q; i++) {
        fgets(line, sizeof(line), stdin);

        int type;
        sscanf(line, "%d", &type);

        if (type == 1) {
            char value[MAX_TEXT];
            sscanf(line, "%d %s", &type, value);

            strcpy(history[++top], text);
            strcat(text, value);
        }
        else if (type == 2) {
            int k;
            sscanf(line, "%d %d", &type, &k);

            strcpy(history[++top], text);
            text[strlen(text) - k] = '\0';
        }
        else if (type == 3) {
            int k;
            sscanf(line, "%d %d", &type, &k);
            printf("%c\n", text[k - 1]);
        }
        else if (type == 4) {
            if (top >= 0) {
                strcpy(text, history[top--]);
            }
        }
    }

    return 0;
}

