import java.util.*;
import java.util.regex.*;

class DinnerPlates {
    private final int capacity;
    private final List<Deque<Integer>> stacks = new ArrayList<>();

    DinnerPlates(int capacity) {
        this.capacity = capacity;
    }

    void push(int value) {
        for (Deque<Integer> stack : stacks) {
            if (stack.size() < capacity) {
                stack.push(value);
                return;
            }
        }

        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(value);
        stacks.add(stack);
    }

    int pop() {
        while (!stacks.isEmpty() && stacks.get(stacks.size() - 1).isEmpty()) {
            stacks.remove(stacks.size() - 1);
        }

        if (stacks.isEmpty()) {
            return -1;
        }

        return stacks.get(stacks.size() - 1).pop();
    }

    int popAtStack(int index) {
        if (index < 0 || index >= stacks.size() || stacks.get(index).isEmpty()) {
            return -1;
        }

        return stacks.get(index).pop();
    }
}

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String input = sc.nextLine().trim();

        Matcher capacityMatcher = Pattern.compile("capacity=(\\d+)").matcher(input);
        if (!capacityMatcher.find()) return;

        int capacity = Integer.parseInt(capacityMatcher.group(1));

