#define MAX_STACKS 1000
#define MAX_CAPACITY 1000

int stacks[MAX_STACKS][MAX_CAPACITY];
int sizes[MAX_STACKS];
int capacity;
int stack_count = 0;

void push(int value) {
    for (int i = 0; i < stack_count; i++) {
        if (sizes[i] < capacity) {
            stacks[i][sizes[i]++] = value;
            return;
        }
    }

    stacks[stack_count][0] = value;
    sizes[stack_count] = 1;
    stack_count++;
}

int pop_stack(void) {
    while (stack_count > 0 && sizes[stack_count - 1] == 0) {
        stack_count--;
    }

    if (stack_count == 0) {
        return -1;
    }

    return stacks[stack_count - 1][--sizes[stack_count - 1]];
}

int pop_at_stack(int index) {
    if (index < 0 || index >= stack_count || sizes[index] == 0) {
        return -1;
    }

    return stacks[index][--sizes[index]];
}

