import java.util.*;

class FreqStack {
    private final Map<Integer, Integer> frequency = new HashMap<>();
    private final Map<Integer, Stack<Integer>> groups = new HashMap<>();
    private int maxFrequency = 0;

    void push(int value) {
        int freq = frequency.getOrDefault(value, 0) + 1;
        frequency.put(value, freq);

        maxFrequency = Math.max(maxFrequency, freq);

        groups.putIfAbsent(freq, new Stack<>());
        groups.get(freq).push(value);
    }

    int pop() {
        Stack<Integer> stack = groups.get(maxFrequency);

        int value = stack.pop();
        frequency.put(value, frequency.get(value) - 1);

        if (stack.isEmpty()) {
            maxFrequency--;
        }

        return value;
    }
}

