#define MAX_VALUE 100000
#define INITIAL_CAPACITY 16

typedef struct {
    int *data;
    int size;
    int capacity;
} IntStack;

void stack_init(IntStack *stack) {
    stack->data = malloc(INITIAL_CAPACITY * sizeof(int));
    stack->size = 0;
    stack->capacity = INITIAL_CAPACITY;
}

void stack_push(IntStack *stack, int value) {
    if (stack->size == stack->capacity) {
        stack->capacity *= 2;
        stack->data = realloc(
            stack->data,
            stack->capacity * sizeof(int)
        );
    }

    stack->data[stack->size++] = value;
}

int stack_pop(IntStack *stack) {
    return stack->data[--stack->size];
}

void stack_free(IntStack *stack) {
    free(stack->data);
}

int main(void) {
    char input[1000000];

    if (fgets(input, sizeof(input), stdin) == NULL) {
        return 0;
    }

    int frequency[MAX_VALUE + 1] = {0};

    IntStack *groups = malloc(
        (MAX_VALUE + 1) * sizeof(IntStack)
    );

    for (int i = 0; i <= MAX_VALUE; i++) {
        groups[i].data = NULL;
        groups[i].size = 0;
        groups[i].capacity = 0;
    }

    int max_frequency = 0;
    int result = -1;
    char *p = input;

    while (*p != '\0') {
        while (*p &&
               (isspace((unsigned char)*p) || *p == ',')) {
            p++;
        }

        if (*p == '\0') {
            break;
        }

        if (strncmp(p, "push", 4) == 0) {
            p += 4;

            while (*p && isspace((unsigned char)*p)) {
                p++;
            }

            int sign = 1;

            if (*p == '-') {
                sign = -1;
                p++;
            }

            int value = 0;

            while (isdigit((unsigned char)*p)) {
                value = value * 10 + (*p - '0');
                p++;
            }

            value *= sign;

            if (value < 0 || value > MAX_VALUE) {
                continue;
            }

            int freq = ++frequency[value];

            if (freq > max_frequency) {
                max_frequency = freq;
            }

            if (groups[freq].data == NULL) {
                stack_init(&groups[freq]);
            }

            stack_push(&groups[freq], value);
        }
        else if (strncmp(p, "pop", 3) == 0) {
            p += 3;

            if (max_frequency > 0 &&
                groups[max_frequency].size > 0) {

                result = stack_pop(&groups[max_frequency]);
                frequency[result]--;

                if (groups[max_frequency].size == 0) {
                    max_frequency--;
                }
            }
        }
        else {
            p++;
        }
    }

    printf("%d", result);

    for (int i = 0; i <= MAX_VALUE; i++) {
        if (groups[i].data != NULL) {
            stack_free(&groups[i]);
        }
    }

    free(groups);

    return 0;
}

