class MinStack {

    Stack<Integer> stack = new Stack<>();
    Stack<Integer> minStack = new Stack<>();

    void push(int val){
        stack.push(val);

        if(minStack.isEmpty() || val <= minStack.peek())
            minStack.push(val);
    }

    int pop(){
        int v = stack.pop();

        if(v == minStack.peek())
            minStack.pop();

        return v;
    }

    int top(){
        return stack.peek();
    }

    int getMin(){
        return minStack.peek();
    }
}

