int main(void) {
    char input[10000];

    if (fgets(input, sizeof(input), stdin) == NULL) {
        return 0;
    }

    int stack[10000];
    int top = -1;

    char *token = strtok(input, "[\", ]\n\r");

    while (token != NULL) {
        if (strcmp(token, "+") != 0 &&
            strcmp(token, "-") != 0 &&
            strcmp(token, "*") != 0 &&
            strcmp(token, "/") != 0) {

            stack[++top] = atoi(token);
        } else {
            int b = stack[top--];
            int a = stack[top--];

            if (strcmp(token, "+") == 0) {
                stack[++top] = a + b;
            } else if (strcmp(token, "-") == 0) {
                stack[++top] = a - b;
            } else if (strcmp(token, "*") == 0) {
                stack[++top] = a * b;
            } else {
                stack[++top] = a / b;
            }
        }

        token = strtok(NULL, "[\", ]\n\r");
    }

    printf("%d", stack[top]);

    return 0;
}

