int main() {

    char s[1000];
    scanf("%s", s);

    char stack_str[100][1000];
    int stack_num[100];

    int top = -1;

    char current[1000] = "";
    int num = 0;

    for (int i = 0; i < strlen(s); i++) {

        char c = s[i];

        if (c >= '0' && c <= '9') {
            num = num * 10 + (c - '0');
        }

        else if (c == '[') {
            top++;
            strcpy(stack_str[top], current);
            stack_num[top] = num;

            current[0] = '\0';
            num = 0;
        }

        else if (c == ']') {

            char temp[1000];
            strcpy(temp, current);

            strcpy(current, stack_str[top]);

            for (int j = 0; j < stack_num[top]; j++) {
                strcat(current, temp);
            }

            top--;
        }

        else {
            int len = strlen(current);
            current[len] = c;
            current[len + 1] = '\0';
        }
    }

    printf("%s", current);
}

