import java.util.*;

public class Solution {

    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);

        Map<Integer,Integer> freq = new HashMap<>();
        Map<Integer,Stack<Integer>> group = new HashMap<>();

        int maxf = 0;
        int result = 0;

        while (sc.hasNext()) {

            String cmd = sc.next();

            if (cmd.equals("push")) {

                int x = sc.nextInt();
                int f = freq.getOrDefault(x,0) + 1;
                freq.put(x,f);

                maxf = Math.max(maxf,f);

                group.putIfAbsent(f,new Stack<>());
                group.get(f).push(x);
            }
            else {

                int x = group.get(maxf).pop();
                freq.put(x,freq.get(x)-1);

                if (group.get(maxf).isEmpty())
                    maxf--;

                result = x;
            }
        }

        System.out.print(result);
    }
}

#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int freq[10000];
int group[10000][1000];
int top[10000];
int maxf = 0;

void push(int x) {

    int f = ++freq[x];

    if (f > maxf) {
        maxf = f;
    }

    group[f][top[f]++] = x;
}

int pop() {

    int x = group[maxf][--top[maxf]];

    freq[x]--;

    if (top[maxf] == 0) {
        maxf--;
    }

    return x;
}

int main() {

    char cmd[20];
    int x;

    int result = 0;

    while (scanf("%s", cmd) != EOF) {

        if (strcmp(cmd, "push") == 0) {
            scanf("%d", &x);
            push(x);
        }

        else if (strcmp(cmd, "pop") == 0) {
            result = pop();
        }
    }

    printf("%d", result);
}

